{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 14,
      "text_ar": "ثم أُعطيت لكم أرض صهيون ملكاً، أما أنتم وآباؤكم فقد ارتكبتم الإثم ولم تحفظوا الطرق التي أمركم بها العلي.",
      "verse": 31
    },
    {
      "chapter": 14,
      "text_ar": "ولأنه قاضٍ عادل، فقد أخذ منكم في الوقت المناسب ما أعطاكم إياه.",
      "verse": 32
    },
    {
      "chapter": 14,
      "text_ar": "والآن أنتم هنا، وأقرباؤكم بينكم.",
      "verse": 33
    },
    {
      "chapter": 14,
      "text_ar": "لذلك إن كنتم ستسودون على فهمكم الخاص وتؤدبون قلوبكم، فستبقون أحياء، وبعد الموت تنالون رحمة.",
      "verse": 34
    },
    {
      "chapter": 14,
      "text_ar": "لأنه بعد الموت ستأتي الدينونة، وحينئذ سنحيا من جديد. وعندئذ ستتضح أسماء الأبرار، وتُعلن أعمال الأشرار.",
      "verse": 35
    }
  ]
}
